import def from "./default/index.js";
import { named } from "./named/index.js";
import { renamed } from "./renamed/index.js";
import { star, absentFromStar } from "./star/index.js";
import { ns } from "./namespace/index.js";
import { deep } from "./deep/index.js";
import { mixed } from "./mixed/index.js";

export default function style() {
	const fn = () => 1;
	// the sole references are dropped by DCE, so nothing requests these names
	// and every barrel keeps its re-export target deferred
	fn.propTypes =
		process.env.NODE_ENV !== "production"
			? { def, named, renamed, star, absentFromStar, ns, deep, mixed }
			: {};
	return fn;
}
